$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;Import-Module (Join-Path $PSScriptRoot 'lib\MorphospaceTransitionLedger.psm1') -Force
function Assert-Ledger {param([bool]$Value,[string]$Message)if(-not$Value){throw "Transition-ledger self-test failed: $Message"}}
function Write-Json {param([string]$Path,[object]$Value)[IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($Path))|Out-Null;[IO.File]::WriteAllText($Path,(($Value|ConvertTo-Json -Depth 20 -Compress)+"`n"),[Text.UTF8Encoding]::new($false))}
$workspace=Join-Path ([IO.Path]::GetTempPath()) ('morphospace-ledger-'+[guid]::NewGuid().ToString('N'))
try{[IO.Directory]::CreateDirectory((Join-Path $workspace 'receipts'))|Out-Null;$state=[pscustomobject]@{schema='test';stage='before'};$unit=[pscustomobject]@{schema='test';status='validating'};$event=[pscustomobject]@{event_id='unit-accept-0001';sequence=1};Write-Json (Join-Path $workspace 'workspace.state.json') $state;Write-Json (Join-Path $workspace 'iteration-units\unit.json') $unit;[IO.File]::WriteAllText((Join-Path $workspace 'iteration-events.jsonl'),'',[Text.UTF8Encoding]::new($false));$targetState=[pscustomobject]@{schema='test';stage='after'};$targetUnit=[pscustomobject]@{schema='test';status='accepted'};$interrupted=$false;try{Start-MorphospaceTransitionLedger -WorkspaceRoot $workspace -TransactionId 'unit-accept-0001' -StatePath 'workspace.state.json' -UnitPath 'iteration-units/unit.json' -EventsPath 'iteration-events.jsonl' -TargetState $targetState -TargetUnit $targetUnit -Event $event -FaultAfter after-projection|Out-Null}catch{$interrupted=$true};Assert-Ledger $interrupted 'fault injection did not interrupt';$result=Complete-MorphospaceTransitionLedger -WorkspaceRoot $workspace -TransactionId 'unit-accept-0001' -Repair;Assert-Ledger ($result.status-eq'committed') 'repair did not commit';Assert-Ledger ((Get-Content (Join-Path $workspace 'workspace.state.json') -Raw|ConvertFrom-Json).stage-eq'after') 'repair did not preserve target state';Assert-Ledger (@(Get-Content (Join-Path $workspace 'iteration-events.jsonl')|Where-Object{$_}).Count-eq1) 'repair event count is not one';Assert-Ledger ((Complete-MorphospaceTransitionLedger -WorkspaceRoot $workspace -TransactionId 'unit-accept-0001').status-eq'already-committed') 'completion was not idempotent';Write-Host 'Transition-ledger self-test passed.'}finally{if([IO.Directory]::Exists($workspace)){[IO.Directory]::Delete($workspace,$true)}}
